/**
 * @vitest-environment jsdom
 */
import { describe, it, expect, vi } from 'vitest';
import { act, createElement } from 'react';
import { createRoot } from 'react-dom/client';

/**
 * R18-014 (giro di correzione, collaudo K07) — Il tetto alla risalita dei genitori c'era solo in
 * lib/category-attributes.ts. Il modulo prodotto risaliva i padri con un suo while (resolveTop)
 * PRIMA di arrivare alla funzione corretta: con categorie A sotto B e B sotto A la pagina girava
 * per sempre. Qui si monta il ProductForm vero; il find delle categorie conta le chiamate e
 * dopo 5.000 si ferma con un errore, così senza la correzione la prova cade invece di bloccarsi.
 */
vi.mock('sonner', () => ({ toast: Object.assign(vi.fn(), { success: vi.fn(), error: vi.fn(), warning: vi.fn(), loading: vi.fn(), dismiss: vi.fn() }) }));
vi.mock('next-intl', () => ({ useTranslations: () => (k: string) => k }));
vi.mock('next/navigation', () => ({ useRouter: () => ({ push: vi.fn() }), usePathname: () => '/' }));
vi.mock('next/image', () => ({ default: () => null }));
vi.mock('@/lib/supabase/client', () => ({
  supabase: { auth: { getSession: async () => ({ data: { session: { access_token: 'tok' } } }), getUser: async () => ({ data: { user: { id: 's1' } } }) } },
}));
(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;

const { default: ProductForm } = await import('@/components/seller/ProductForm');

type Cat = { id: string; name: string; slug: string; parent_id: string | null };
const TETTO = 5000;

function conConteggio(lista: Cat[]) {
  const conto = { chiamate: 0 };
  Object.defineProperty(lista, 'find', {
    value(this: Cat[], ...a: Parameters<Cat[]['find']>) {
      if (++conto.chiamate > TETTO) throw new Error(`categorie: ${conto.chiamate} chiamate a find, la risalita gira in tondo`);
      return Array.prototype.find.apply(this, a as never);
    },
  });
  return conto;
}

async function monta(categorie: Cat[], categoryId: string) {
  const box = document.createElement('div');
  document.body.appendChild(box);
  const root = createRoot(box);
  let errore: unknown = null;
  try {
    await act(async () => {
      root.render(createElement(ProductForm, {
        mode: 'edit', categories: categorie, aiAccesa: false, sellerOffersExpress: false, consegnaDelNegozioNonLetta: false,
        onSubmit: () => {},
        initialValues: { name: 'Vaso', description: 'Vaso in ceramica fatto a mano', price: 10, unit: 'pezzo', stock: 1,
          category_id: categoryId, images: ['https://x/1.jpg'], attributes: {}, tags: [], status: 'draft', variants: [] },
      }));
    });
  } catch (e) { errore = e; }
  const etichetta = (t: string) => [...box.querySelectorAll('label')].find((l) => (l.textContent ?? '').includes(t));
  const selectDi = (t: string) => {
    const l = etichetta(t);
    const id = l?.getAttribute('for');
    return (id ? document.getElementById(id) : l?.parentElement?.querySelector("select")) as HTMLSelectElement | null;
  };
  return { box, errore, selectDi, smonta: () => { act(() => root.unmount()); box.remove(); } };
}

describe('R18-014 — il modulo prodotto regge un cerchio nelle categorie', () => {
  it('categorie A⇄B: il modulo si apre, senza girare in tondo', async () => {
    const categorie: Cat[] = [
      { id: 'a', name: 'Cerchio A', slug: 'cerchio-a', parent_id: 'b' },
      { id: 'b', name: 'Cerchio B', slug: 'cerchio-b', parent_id: 'a' },
      { id: 'casa', name: 'Casa', slug: 'casa', parent_id: null },
    ];
    const conto = conConteggio(categorie);
    const m = await monta(categorie, 'a');
    expect(m.errore, String((m.errore as Error)?.message ?? '')).toBeNull();
    expect(conto.chiamate).toBeLessThan(TETTO);
    expect(m.box.textContent).toContain('Categoria');
    m.smonta();
  });

  it('controprova: una sottocategoria vera mostra ancora la sua radice e se stessa', async () => {
    const categorie: Cat[] = [
      { id: 'casa', name: 'Casa', slug: 'casa', parent_id: null },
      { id: 'vasi', name: 'Vasi', slug: 'vasi', parent_id: 'casa' },
      { id: 'sport', name: 'Sport', slug: 'sport', parent_id: null },
    ];
    conConteggio(categorie);
    const m = await monta(categorie, 'vasi');
    expect(m.errore).toBeNull();
    expect(m.selectDi('Categoria')?.value).toBe('casa');
    expect(m.selectDi('Sottocategoria')?.value).toBe('vasi');
    m.smonta();
  });
});

